import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken(); long a = (long)in.nval;
        in.nextToken(); long b = (long)in.nval;
        in.nextToken(); long c = (long)in.nval;
        in.nextToken(); long l = (long)in.nval;

        long total = 0;
        for (long d = 0; d <= l; d++) {
            total += (d + 1) * (d + 2) / 2;
        }
        total -= bad(a, b, c, l);
        total -= bad(b, a, c, l);
        total -= bad(c, a, b, l);
        System.out.println(total);
    }

    static long bad(long a, long b, long c, long l) {
        long res = 0;
        for (long i = 0; i <= l; i++) {
            long m = Math.min(l - i, a + i - b - c);
            if (m >= 0) {
                res += (m + 1) * (m + 2) / 2;
            }
        }
        return res;
    }
}
